import React, { useState, useEffect } from "react";
import { BellIcon } from "@heroicons/react/24/outline";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import ConfirmLogoutModal from "../components/ConfirmLogoutModal";

import { auth } from "../firebase";
import { onAuthStateChanged, signOut } from "firebase/auth";

const TopBar = () => {
  const [dropdown, setDropdown] = useState(false);
  const [showLogoutModal, setShowLogoutModal] = useState(false);

  const [userName, setUserName] = useState("User");
  const [avatar, setAvatar] = useState("");

  const navigate = useNavigate();

  // 🔥 REAL FIREBASE USER (NO LOCALSTORAGE)
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        setUserName(user.displayName || "User");

        if (user.photoURL) {
          setAvatar(user.photoURL);
        } else {
          const initial = (user.displayName || "U")
            .charAt(0)
            .toUpperCase();

          setAvatar(
            `https://ui-avatars.com/api/?name=${initial}&background=6366f1&color=fff&bold=true`
          );
        }
      }
    });

    return () => unsubscribe();
  }, []);

  const handleLogout = async () => {
    await signOut(auth);
    toast.success("Logged out!");
    navigate("/login");
  };

  return (
    <>
      {/* TOP BAR */}
      <div className="ml-64 h-14 px-6 flex items-center justify-between border-b bg-white/80 backdrop-blur-md sticky top-0 z-50">

        {/* SEARCH (Notion style) */}
        <div className="flex items-center w-1/3">
          <div className="w-full bg-gray-100 hover:bg-gray-200 transition rounded-md px-3 py-1.5 text-sm text-gray-600">
            Search...
          </div>
        </div>

        {/* RIGHT SECTION */}
        <div className="flex items-center gap-4">

          {/* NOTIFICATION */}
          <button className="p-2 rounded-md hover:bg-gray-100 transition">
            <BellIcon className="h-5 w-5 text-gray-600" />
          </button>

          {/* DIVIDER */}
          <div className="w-px h-6 bg-gray-200"></div>

          {/* PROFILE */}
          <div className="relative">

            <button
              onClick={() => setDropdown(!dropdown)}
              className="flex items-center gap-2 px-2 py-1 rounded-md hover:bg-gray-100 transition"
            >
              {/* AVATAR */}
              <img
                src={avatar}
                alt="Profile"
                className="w-7 h-7 rounded-full object-cover border border-gray-200"
              />

              {/* NAME */}
              <span className="text-sm font-medium text-gray-700">
                {userName}
              </span>

              {/* ARROW */}
              <svg
                className={`w-4 h-4 text-gray-500 transition-transform ${
                  dropdown ? "rotate-180" : ""
                }`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M19 9l-7 7-7-7"
                />
              </svg>
            </button>

            {/* DROPDOWN (Notion style) */}
            {dropdown && (
              <div className="absolute right-0 mt-2 w-56 bg-white border border-gray-200 rounded-lg shadow-lg overflow-hidden">

                {/* USER INFO */}
                <div className="px-4 py-3 border-b">
                  <p className="text-sm font-medium text-gray-900">
                    {userName}
                  </p>
                  <p className="text-xs text-gray-500 truncate">
                    {auth.currentUser?.email}
                  </p>
                </div>

                {/* MENU */}
                <button
                  onClick={() => {
                    navigate("/profile");
                    setDropdown(false);
                  }}
                  className="w-full text-left px-4 py-2 text-sm hover:bg-gray-100"
                >
                  Profile
                </button>

                <button
                  onClick={() => {
                    setShowLogoutModal(true);
                    setDropdown(false);
                  }}
                  className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50"
                >
                  Sign out
                </button>
              </div>
            )}

          </div>
        </div>
      </div>

      {/* LOGOUT MODAL */}
      <ConfirmLogoutModal
        isOpen={showLogoutModal}
        onClose={() => setShowLogoutModal(false)}
        onConfirm={handleLogout}
      />
    </>
  );
};

export default TopBar;
